data.query:
query Query($inventoryNumber: String!) {
  inventory(where: {number:{_eq:$inventoryNumber} active:{_eq:true}}) {
    edges {
      node {
        id
				active
        number
        transactionTypeId
        location {
          id
          name
          locationType {
            id
            name
            inventory
            qualityHold
          }
        }
        inventoryStatus {
          id
          name
          active
          suspect
        }
        quantity {
          value
          unitId
        }
        weightUnit {
          id
          code
        }
        grossWeight
        netWeight
        tareWeight
        inventoryStatus {
          id
          name
          active
          moveLock
          mergeLock
          splitLock
        }
        masterInventory {
          id
          number
          masterInventoryStatus {
            id
            name
            active
            moveLock
            mergeLock
          }
        }
        supplier {
          id
          name
          externalId
          status
        }
        productStrategyProcess {
          id
          code          
          unitWeight
          productStrategy {
            id
            code
            name
            product {
              id
              code
              name
            }
          }
        }
      }
    }
  }
  productionSetupMaterial(where:{inventory:{number:{_eq:$inventoryNumber}}}) {
    edges {
      node {
        id
        number
        productionSetup {
          id
          workcenter {
            name
          }
        }
      }
    }
  }
  transactionType(where:{inventorySplit:{_eq:true}} first:1) {
    edges {
      node {
        id
      }
    }
  }
}

data.variablesTransform:
(
  /* Grab Information about the Request */
  $numberOfContainers := $state.context.REQUEST.numberOfContainers;
  $quantityPerContainer := $state.context.REQUEST.quantityPerContainer;

  /* Grab information about the inventory currently in the system */
  $fromInventory := $state.context.QUERY.inventory.edges.node.id;
  $originalContainerQuantity := $state.context.QUERY.inventory.edges.node.quantity.value;
  $inventoryStatusId := $state.context.QUERY.inventory.edges.node.inventoryStatus.id;
  $inventoryLocationId := $state.context.QUERY.inventory.edges.node.locationId;
  $productStrategyProcess := $state.context.QUERY.inventory.edges.node.productStrategyProcessId;
  $quantityUnitId := $state.context.QUERY.inventory.edges.node.quantity.unitId;
  $weightUnitId := $state.context.QUERY.inventory.edges.node.weightUnit.id;
  $quantityUnitId := $state.context.QUERY.inventory.edges.node.quantity.unitId;
  $grossWeight := $coalesce([$state.context.QUERY.inventory.edges.node.grossWeight,0]);
  $netWeight := $coalesce([$state.context.QUERY.inventory.edges.node.netWeight,0]);
  $tareWeight := $coalesce([$state.context.QUERY.inventory.edges.node.tareWeight,0]);

  /* Grab information about the transaction type to use for new containers */
  $newTransactionTypeId := $state.context.QUERY.transactionType.edges.node.id;

  /* Calculate the quantity being used per new container*/
  $quantityConsumed := $numberOfContainers * $quantityPerContainer;

  /* Calculate the average weight of each unit on the existing container */
  $weightPerUnit := $netWeight/$originalContainerQuantity;

  /* Calculate the original container's new values */
  $originalContainerNewQuantity := ($originalContainerQuantity - $quantityConsumed);
  $originalContainerNewNetWeight := $originalContainerNewQuantity * $weightPerUnit;
  $originalContainerNewGrossWeight := $originalContainerNewNetWeight + $tareWeight;
  $originalContainerNewActiveFlag := $originalContainerNewQuantity>0;

  /* Calculate new weights, assume the same tare weight and unit of measure */
  $newContainerNetWeight := $quantityPerContainer * $weightPerUnit;
  $newContainerTareWeight := $tareWeight;
  $newContainerGrossWeight := $newContainerNetWeight + $newContainerTareWeight;
  $newContainerWeightUnitId := $weightUnitId;

  {
    "createPayload": [1..$numberOfContainers].{
      "create": {
        "inventoryStatusId": $inventoryStatusId,
        "locationId": $inventoryLocationId,
        "productStrategyProcessId": $productStrategyProcess,
        "inventoryTypeId": $state.context.QUERY.inventory.edges.node.inventoryTypeId,
        "weightUnitId": $weightUnitId,
        "netWeight": $newContainerNetWeight,
        "tareWeight": $newContainerTareWeight,
        "grossWeight": $newContainerGrossWeight,
        "quantity": {
          "value": $quantityPerContainer,
          "unitId": $quantityUnitId
        }
      }
    },
    "updatePayload": {
      "update": {
        "active": $originalContainerNewActiveFlag,
        "netWeight": $originalContainerNewNetWeight,
        "grossWeight": $originalContainerNewGrossWeight,
        "quantity": {
          "value": $originalContainerNewQuantity,
          "unitId": $quantityUnitId
        }
      },
      "where": {
        "id": $fromInventory
      }
    }
  }
)

